mapper.select:
select ct.id, ct.orgId, ct.tariffCategoryId, ct.tariffCategoryName, ct.tariffCategoryNumber, ct.tariffId, ct.`name`, ct.englishName, ct.`number`, ct.unit, ct.price, ct.inservice from ( select ct.id, ct.clinic_id as orgId, btbtc.tariffCategoryId, btbtc.tariffCategoryName, btbtc.tariffCategoryNumber, btbtc.tariffId, btbtc.`name`, btbtc.pinyin, btbtc.englishName, btbtc.`number`, btbtc.unit, ct.price, ct.inservice from clinic_tariff ct left join ( select bt.id as tariffId, btc.id as tariffCategoryId, btc.`name` as tariffCategoryName, btc.number as tariffCategoryNumber, bt.item_number as number, bt.`name`, bt.pinyin, bt.english_name as englishName, unit from base_tariff bt left join base_tariff_category btc on bt.tariff_category_id = btc.id ) btbtc on ct.tariff_id = btbtc.tariffId ) ct
and ct.id = #{queryForm.id}
and ct.orgId =#{queryForm.orgId}
and ct.tariffCategoryId = #{queryForm.tariffCategoryId}
and ct.tariffId = #{queryForm.tariffId}
and ct.name like concat('%',#{queryForm.keyWord},'%') or ct.pinyin like concat('%',#{queryForm.keyWord},'%') or ct.englishName like concat('%',#{queryForm.keyWord},'%')
and ct.inservice = #{queryForm.inservice}
